const fs=require('fs'),ts=require('typescript'),assert=require('assert/strict');const m={exports:{}};new Function('require','module','exports',ts.transpileModule(fs.readFileSync('src/lib/store/home-price-overlay.ts','utf8'),{compilerOptions:{module:1,target:9}}).outputText)(()=>{throw Error('No runtime DB/session dependency allowed in merge')},m,m.exports);const merge=m.exports.attachHomePrices;const products=[{id:'one',name:'Product One',moq:40,sold_out:false,name_en:'Product One'},{id:'deleted',name:'Deleted Product',moq:1}];const prices=[{id:'one',price:123,wholesale_price:100,compare_at_price:200,stock:0,moq:45,sold_out:true,updated_at:'now'}];assert.strictEqual(merge(products,prices,'guest'),products);assert(!('price' in merge(products,prices,'guest')[0]));for(const role of ['member','admin']){const result=merge(products,prices,role);assert.equal(result.length,1);assert.equal(result[0].price,123);assert.equal(result[0].moq,45);assert.equal(result[0].sold_out,true);assert.equal(result[0].name_en,'Product One');}assert(!('price' in products[0]));assert.equal(products[0].moq,40);assert.equal(merge(products,[],'member').length,0);console.log('PASS public selection unchanged; guest prices excluded; current member/admin prices, MOQ and sold-out applied; archived/deleted rows removed; public cache objects not mutated.');
